select bdsc.id, bdsc.year, bdsc.target_type, bdsc.target_name, bdsc.target_value from bi_data_source_custom bdsc
and bdsc.data_type = #{params.dataType}
and bdsc.type = #{params.type}
and bdsc.target_name like concat('%',#{params.targetName},'%')
and bdsc.create_time >= #{params.createTime_begin}::timestamp
and bdsc.create_time <= #{params.createTime_end}::timestamp

